import React, { useEffect, useRef } from 'react';
import { useParams } from 'react-router-dom';

function TerminalComponent() {
  const params = useParams();
  const containerId = params.containerId; // Get containerId from route parameters
  const socketRef = useRef(null); // Reference to hold WebSocket connection

  useEffect(() => {
    // Initialize WebSocket connection
    socketRef.current = new WebSocket('ws://localhost:3001');

    // Set up WebSocket event listeners
    socketRef.current.onopen = () => {
      console.log('WebSocket connection established');
      // Send initial message to start a shell session in the Docker container
      socketRef.current.send(JSON.stringify({ containerId, cmd: '/bin/sh' }));
    };

    socketRef.current.onmessage = (event) => {
      const message = JSON.parse(event.data);
      // Handle output or errors from WebSocket message
      if (message.output) {
        console.log('Container Output:', message.output); // Log output to console (replace with UI update as needed)
      } else if (message.error) {
        console.log('Container Error:', message.error); // Log errors to console
      } else if (message.message) {
        console.log('Message:', message.message); // Log process exit message
      }
    };

    socketRef.current.onclose = () => {
      console.log('WebSocket connection closed');
    };

    socketRef.current.onerror = (error) => {
      console.error('WebSocket error:', error);
    };

    // Clean up WebSocket on component unmount
    return () => {
      if (socketRef.current) {
        socketRef.current.close();
      }
    };
  }, [containerId]);

  return (
    <div
      style={{
        margin: "30px",
        width: '1400px',
        height: '700px',
        backgroundColor: "black",
        color: "white",
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        fontSize: '20px'
      }}
    >
      Container ID: {containerId}
    </div>
  );
}

export default TerminalComponent;
